SELECT 
FROM dbo.ReadingList l WITH (UPDLOCK, ROWLOCK)
WHERE l.ListId = #{listId} AND l.UserId = #{userId}

mapper.update:
UPDATE dbo.ReadingList
Name = #{name}, Description = #{description, jdbcType=NVARCHAR}, IsPublic = #{isPublic}, UpdatedAt = SYSUTCDATETIME()
WHERE ListId = #{listId}

mapper.insert:
INSERT dbo.ReadingListItem (ListId, StoryId, OrderNo, Note)
SELECT #{listId}, #{storyId}, ISNULL(MAX(i.OrderNo), 0) + 1, #{note, jdbcType=NVARCHAR}
FROM dbo.ReadingListItem i
WHERE i.ListId = #{listId}

mapper.update:
UPDATE dbo.ReadingList
SET ItemCount = ItemCount + #{delta}, UpdatedAt = SYSUTCDATETIME()
WHERE ListId = #{listId}

mapper.select:

WHERE i.ListId = #{listId}
ORDER BY i.OrderNo, i.StoryId
OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

